<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'withdrawals.list',60,60);$page=max(1,min(100000,(int)($_GET['page']??1)));$stmt=db()->prepare('SELECT withdrawal_id,amount,payment_method,payment_account_masked,payment_reference,status,risk_level,requested_at,reviewed_at,processed_at,rejection_reason FROM withdrawals WHERE user_id=? ORDER BY id DESC LIMIT 20 OFFSET '.(($page-1)*20));$stmt->execute([$user['id']]);json_response(true,'Withdrawals retrieved',['items'=>$stmt->fetchAll(),'page'=>$page]);
